workflow_blocks.script:
set -Eeuo pipefail
python3 - <<'PY'
from pathlib import Path
release=Path('hermes-dev-v2/dvizhrelease.py').read_text()
push=Path('hermes-dev-v2/dvizhgitpush.py').read_text()
required_release=[
  '"/opt/dvizh/static/index.html"',
  '"/opt/dvizh/static/ai-home-v2.js"',
  '"/opt/dvizh/static/ai-home-v2.css"',
  '"/opt/dvizh/server.py"',
  'ALLOWED_RESTARTS',
  'target is outside the release allowlist',
  'approval challenge does not match this exact proposal',
]
for marker in required_release:
  if marker not in release: raise SystemExit(f'missing release marker: {marker}')
required_push=[
  'FRIEND_PROJECT_MARKERS', 'CONTROL_PLANE_DENY',
  'friend-project/out-of-scope paths',
  'merge commits are not allowed',
  'git@github.com:{REPO}.git',
]
for marker in required_push:
  if marker not in push: raise SystemExit(f'missing push marker: {marker}')
for forbidden in ['/etc/systemd/system/', '/var/lib/dvizh/auth', 'iptables', 'ufw ', 'authorized_keys']:
  if forbidden in release + push: raise SystemExit(f'forbidden root surface: {forbidden}')
if 'git push --force' in push or 'reset --hard' in push:
  raise SystemExit('unsafe Git primitive')
PY
